请对以下 case 进行三维加权评分。

=== case_id ===
Case-11-fitness-005

=== 用户原始指令 (query.txt) ===
健身总结卡,一句话带数字那种,点跳app,显示已连设备

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "健身总结卡,一句话带数字那种,点跳app,显示已连设备",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/home/sport?sportType=2"
      }
    }
  ],
  "dataModelSchema": {
    "summary": {
      "title": {
        "type": "string",
        "description": "健身总结卡片标题",
        "sampleValue": "健身总结"
      },
      "deviceStatusText": {
        "type": "string",
        "description": "设备连接状态短文本",
        "sampleValue": "已连设备"
      },
      "sentence": {
        "type": "string",
        "description": "带数字的一句话健身总结",
        "sampleValue": "今天运动 48 分钟"
      },
      "caloriesText": {
        "type": "string",
        "description": "本次或今日运动热量消耗展示文本",
        "sampleValue": "燃烧 520 千卡"
      },
      "deviceLine": {
        "type": "string",
        "description": "已连接设备展示文本",
        "sampleValue": "已连 Watch GT 4"
      },
      "actionLabel": {
        "type": "string",
        "description": "打开运动健康应用的短动作文案",
        "sampleValue": "打开应用"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/figure_run.svg",
      "description": "跑步人物黑色线性图标，适合用于运动记录、跑步锻炼追踪与健身总结卡片的主识别图形。"
    }
  ]
}

